-- Hand-labeled ground truth. Written only by `scout label`; never generated by an LLM.
CREATE TABLE labels (
    item_id      TEXT PRIMARY KEY REFERENCES items (id),
    relevance    INTEGER NOT NULL CHECK (relevance BETWEEN 0 AND 3),
    faithfulness INTEGER CHECK (faithfulness BETWEEN 1 AND 5),
    coverage     INTEGER CHECK (coverage BETWEEN 1 AND 5),
    conciseness  INTEGER CHECK (conciseness BETWEEN 1 AND 5),
    entities_ok  INTEGER CHECK (entities_ok IN (0, 1)),
    labeled_at   TEXT NOT NULL
);
